```ts
import {
  createArcRotateCamera,
  attachControl,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(
  canvas: HTMLCanvasElement,
  scene: SceneContext
): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });
  enableArcRotateKeyboardControls();
  attachControl(camera, canvas, scene, { keyboard: true });
  return camera;
}
```

I created `src/orbit-camera.ts` which builds an `ArcRotateCamera` at radius 10 targeting the origin, calls `enableArcRotateKeyboardControls()` (required per note 9 before `keyboard: true` is honoured), and then attaches the standard pointer and keyboard controls via `attachControl`. The one thing I'm not fully sure of is whether `SceneContext` and the factory functions are all re-exported from the `@babylonjs/lite` package root or whether some need a sub-path import; I assumed they are all available at the top level since you told me the library is imported as `@babylonjs/lite`.
